import{z as i,x as l,o as t,c as d,q as r,j as A,D as E,d as e,s as B,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"快照隔离","description":"","frontmatter":{"title":"快照隔离","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/snapshot-isolation.md","filePath":"cs/snapshot-isolation.md","lastUpdated":1791413859000}'),p={name:"cs/snapshot-isolation.md"};function m(T,a,S,c,h,D){const o=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="快照隔离" tabindex="-1">快照隔离 <a class="header-anchor" href="#快照隔离" aria-label="Permalink to &quot;快照隔离&quot;">​</a></h1><div class="epigraph"><p>事务读一个已提交快照，写在提交时若写集与并发已提交者冲突则中止；它不是冲突可串行，但很常见。</p><footer>—— 据 Berenson et al., SIGMOD 1995；Reed 对多版本；Ramakrishnan 对照</footer></div><p><a href="/cs/mvcc">上一课</a>让读选可见版本、写建新版。本课不重写可见性函数。缺口是广泛实现的一种调度：<strong>快照隔离（SI）</strong>。读不取锁，提交时检查写–写。幻读与写偏斜下一课专收。隔离级别表更后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MVCC 课留下「读按快照」。SI 把快照钉在事务开始（或第一条语句），提交用「第一提交者胜」的写集冲突：与已提交的重叠写则 abort。它禁止脏读、不可重复读（对自己的快照），仍允许下一课的写偏斜。缺口是<strong>把 SI 从「有版本」里命名出来</strong>，避免当成可串行。</p><p><span class="marginnote">术语翻译：「第一提交者胜」就是——两个事务改同一行时，谁先走到提交那一刻谁赢，后到者整个回滚重试。注意它只比较<strong>写集</strong>：读过的数据不参与检查，这正是写偏斜能从检查缝里溜过去的原因。</span></p><p><span class="marginnote">SSI（可串行快照隔离）后来加冲突监测逼近可串行。主干先钉经典 SI，不把 SSI 当默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开始：记 startTS。读：最新的 committedTS \\(\\lt\\) startTS 的版本（加上自己的写）。写：私有直到提交，再分配 commitTS 并检查写集。失败则整个事务撤，靠 WAL UNDO。本课不把每家数据库默认级别写成同一 SI。</p>',9)),(t(),A(n,null,{default:E(()=>[B(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E8%AE%B0%E5%BF%AB%E7%85%A7%E6%97%B6%E9%97%B4%22%5D%20--%3E%20READ%5B%22%E8%AF%BB%E8%AF%A5%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%E7%89%88%E6%9C%AC%22%5D%0A%20%20READ%20--%3E%20WSET%5B%22%E7%B4%AF%E7%A7%AF%E5%86%99%E9%9B%86%22%5D%0A%20%20WSET%20--%3E%20CHK%5B%22%E6%8F%90%E4%BA%A4%E6%97%B6%E5%86%99%E5%86%99%E5%86%B2%E7%AA%81%E5%88%99%E4%B8%AD%E6%AD%A2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"SI 用版本换掉读锁，写锁或占用仍常在，避免 ww。冲突可串行要求的 rw 边可以成环而不被检测——写偏斜。后课用保险与医生的经典例子说明规格差在哪。对只读只读快照，近似理想。",-1)),(t(),A(n,null,{default:E(()=>[B(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BA%8B%E5%8A%A1%20T1%20%E8%AF%BB%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20W1%5B%22T1%20%E7%A7%81%E4%B8%8B%E6%94%B9%20%E7%B4%AF%E7%A7%AF%E5%86%99%E9%9B%86%20A%22%5D%0A%20%20T2%5B%22%E4%BA%8B%E5%8A%A1%20T2%20%E8%AF%BB%E5%90%8C%E4%B8%80%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20W2%5B%22T2%20%E7%A7%81%E4%B8%8B%E6%94%B9%20%E7%B4%AF%E7%A7%AF%E5%86%99%E9%9B%86%20B%22%5D%0A%20%20W1%20--%3E%20C%7B%22%E6%8F%90%E4%BA%A4%E6%97%B6%E5%86%99%E9%9B%86%E4%B8%8E%E5%B7%B2%E6%8F%90%E4%BA%A4%E8%80%85%E9%87%8D%E5%8F%A0%3F%22%7D%0A%20%20W2%20--%3E%20C%0A%20%20C%20--%20%22A%20%E4%B8%8E%20B%20%E4%B8%8D%E7%9B%B8%E4%BA%A4%22%20--%3E%20OK%5B%22%E4%B8%A4%E8%80%85%E9%83%BD%E6%8F%90%E4%BA%A4%E6%88%90%E5%8A%9F%22%5D%0A%20%20OK%20--%3E%20BR%5B%22rw%20%E8%BE%B9%E6%88%90%E7%8E%AF%E6%97%A0%E4%BA%BA%E6%A3%80%E6%B5%8B%3A%20%E5%86%99%E5%81%8F%E6%96%9C%20%E4%B8%8D%E5%8F%98%E5%BC%8F%E8%A2%AB%E6%89%93%E7%A0%B4%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字实例：把时间戳当序号看——T1 的 startTS=100，T2 的 startTS=101，两者读到的都是 100 之前已提交的版本；T1 commitTS=105 先到，T2 commitTS=106 后到。若都写第 7 行，T2 撞上 T1 的已提交写集、整个回滚；若写的行不相交，则双双成功——而业务不变式可能已经坏了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把快照当备份工具（时间点恢复是日志另一用法）。哪些异常 SI 还放行，下一课幻读与写偏斜。</p><p><span class="marginnote">常见误区：以为「没有脏读、没有不可重复读」就等于数据安全。SI 只保证你看到一致快照、你的写不与他人撞车；两个事务各改各的、合起来破坏业务不变式（例如「值班医生至少一人在线」），SI 并不拦截——这要等 SSI 加冲突监测，或者显式上锁。</span></p><p>后课默认：SI 是 MVCC 上最常见的产品点。它还不是可串行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SI：读快照，提交查写集。</li><li>无脏读，仍可能写偏斜。</li><li>幻读与写偏斜下一课。</li><li>出处：Berenson et al., 1995；Reed 1978。</li></ul>',7))])}const f=i(p,[["render",m]]);export{_ as __pageData,f as default};
